<div class="om-grid">
  <section class="om-box"><h4>Order</h4><dl class="om-dl"><dt>Order ID</dt><dd class="font-mono"><b><?= e($o['reference']) ?></b></dd><dt>Order date</dt><dd><?= e(date('d M Y, h:i A', strtotime($o['created_at']))) ?></dd><dt>Status</dt><dd><?= status_badge($o['status']) ?></dd><dt>Source</dt><dd><?= e(ucwords(str_replace('_', ' ', $o['order_source']))) ?></dd><?php if ($o['tracking_info']): ?><dt>Tracking</dt><dd><?= e($o['tracking_info']) ?></dd><?php endif; ?></dl></section>
  <section class="om-box"><h4>Customer</h4><dl class="om-dl"><dt>Name</dt><dd><b><?= e($o['customer_name']) ?></b></dd><dt>Mobile</dt><dd><a class="text-primary" href="tel:<?= e($o['mobile']) ?>"><?= e($o['mobile']) ?></a></dd><dt>Email</dt><dd><?= $o['email'] ? e($o['email']) : '<span class="muted">—</span>' ?></dd></dl></section>
  <section class="om-box"><h4>Shipping address</h4><p class="om-p"><?= nl2br(e($o['address'])) ?><br><?= e($o['city']) ?>, <?= e($o['state']) ?> – <?= e($o['pincode']) ?><?= $o['landmark'] ? '<br><span class="muted">Landmark:</span> ' . e($o['landmark']) : '' ?></p><?php if ($o['notes']): ?><p class="om-note"><b>Customer note:</b> <?= e($o['notes']) ?></p><?php endif; ?></section>
  <section class="om-box"><h4>Payment</h4><dl class="om-dl"><dt>Method</dt><dd><?= e($inv['method_label']) ?></dd><dt>Payment status</dt><dd><span class="badge <?= $o['payment_status'] === 'paid' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-800' ?>"><?= e(ucfirst($o['payment_status'])) ?></span></dd></dl></section>
</div>
<h4 class="om-h">Products</h4>
<div class="om-scroll"><table class="table-x w-full text-sm"><thead><tr><th>Product</th><th class="text-center">Qty</th><th class="text-right">Original price</th><th class="text-right">Discount price</th><th class="text-right">Final amount</th></tr></thead><tbody>
<?php foreach ($inv['lines'] as $l): ?><tr><td><b><?= e($l['name']) ?></b><div class="text-xs muted font-mono"><?= e($l['sku']) ?></div></td><td class="text-center"><?= (int)$l['qty'] ?></td><td class="text-right"><?= $l['discount_unit'] > 0 ? '<s class="muted">' . money($l['original_price']) . '</s>' : money($l['original_price']) ?></td><td class="text-right"><?= money($l['unit_price']) ?><?php if ($l['discount_unit'] > 0): ?><div class="text-xs text-green-700">− <?= money($l['discount_unit']) ?> each</div><?php endif; ?></td><td class="text-right"><b><?= money($l['line_total']) ?></b></td></tr><?php endforeach; ?></tbody></table></div>
<dl class="om-sum"><div><dt>Subtotal (original price)</dt><dd><?= money($inv['subtotal']) ?></dd></div>
  <?php if ($inv['item_discount'] > 0): ?><div class="g"><dt>Discount<?= $pct !== '' && $pct !== '0' ? ' (' . e($pct) . '%)' : '' ?></dt><dd>− <?= money($inv['item_discount']) ?></dd></div><?php endif; ?>
  <?php if ($inv['extra_discount'] > 0): ?><div class="g"><dt>Additional discount</dt><dd>− <?= money($inv['extra_discount']) ?></dd></div><?php endif; ?>
